// === Tab: Cell ===
class Cell {
  constructor(x, y, s) {
    this.x = x;
    this.y = y;
    this.s = s;
    this.isOpen = false;
    this.isBug = false;
    this.isMarked = false;
    this.near = 0;
  }

  draw() {
    push();
    noStroke();

		// cell background
    fill(64);
    if (this.isOpen && this.isBug) {
      fill("red");
    } else if (!this.isOpen) {
      fill(212 + sin(frameCount * 0.1) * 24);
    }
    rect(this.x * this.s, this.y * this.s, this.s - 1, this.s - 1, 5, 5, 5, 5);

		// cell info
		let info = "";
    if (this.isMarked) {
      fill(32, 192, 164);
      rect(this.x * this.s, this.y * this.s, this.s - 1, this.s - 1);

      fill("azure");
      // text("🚩", this.x * this.s + this.s / 2, this.y * this.s + this.s / 2);
			info = "🚩";
    } else if (this.isOpen) {
      if (this.isBug) {
        // show bug
        fill(222);
        // text("🐴", this.x * this.s + this.s / 2, this.y * this.s + this.s / 2);
				info = "🦄";
      } else {
        // show near bys
        fill(222);
        if (this.near > 0) fill(32, 192, 164);
        if (this.near > 1) fill("yellow");
        if (this.near > 2) fill("red");
        if (this.near > 3) fill("purple");
        // text(this.near, this.x * this.s + this.s / 2, this.y * this.s + this.s / 2);
				info = this.near;
      }
    }
		if (gameLost && this.isBug) info = "🦄";
		textAlign(CENTER, CENTER);
		textSize(this.s * 0.8);
		noStroke();
		text(info, this.x * this.s + this.s / 2, this.y * this.s + this.s / 2);

    pop();
  }

  open() {
    if (this.isOpen || this.isMarked) return;

    this.isOpen = true;
    if (this.near === 0) {
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          const xx = this.x + dx;
          const yy = this.y + dy;
          if (xx >= 0 && xx < gx && yy >= 0 && yy < gy) {
            grid[yy][xx].open();
          }
        }
      }
    }
  }

  toggleMark() {
    if (this.isOpen) return;

    this.isMarked = !this.isMarked;
  }

  setBug() {
    if (this.isBug) return;

    this.isBug = true;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        var xx = this.x + dx;
        var yy = this.y + dy;
        if (xx >= 0 && xx < gx && yy >= 0 && yy < gy) {
          grid[yy][xx].near++;
        }
      }
    }
  }
}

