	dont disturb the unicorns, else they will loose their magic.
	Hopefully teh emojis will be displayed on all devices...

	There is a trick to always win the game - a wish comes true, if you find it :-)

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

var grid, gs;
var gx = 15;
var gy = 15;
var bugs = (gx * gy) / 10;

var startTime, currTime;
var areOpen = 0,
  areMarked = 0,
  gameLost = false,
  gameWon = false;

function setup() {
	gs = ~~min(windowWidth/gx, windowHeight/(gy+1));
  createCanvas(gx * gs, (gy + 1) * gs);
	describe("Mine sweeper game with unicorns - which are not horses ^^");
  for (let element of document.getElementsByClassName("p5Canvas")) {
    element.addEventListener("contextmenu", (e) => e.preventDefault());
  }
  initGrid(bugs);
  frameRate(60);
}

function initGrid(bugs) {
  grid = new Array(gy);
  for (let yy = 0; yy < gy; yy++) {
    grid[yy] = new Array(gx);
    for (let xx = 0; xx < gx; xx++) {
      grid[yy][xx] = new Cell(xx, yy, gs);
    }
  }

  for (let i = 0; i < bugs; i++) {
    var xx = floor(random(gx));
    var yy = floor(random(gy));
    grid[yy][xx].setBug();
  }

  startTime = millis();
  currTime = startTime;
}

function draw() {
  background(32);

  areOpen = 0;
  areMarked = 0;
  gameLost = false;
  for (let yy = 0; yy < gy; yy++) {
    for (let xx = 0; xx < gx; xx++) {
      const cell = grid[yy][xx];
      cell.draw();
      if (cell.isOpen && cell.isBug) {
        // print("game over");
        gameLost = true;
      }
      if (cell.isOpen) areOpen++;
      if (cell.isMarked) areMarked++;
    }
  }
  // print("*", gx*gy, areOpen, areMarked, gx*gy-areOpen-areMarked)

  gameWon = !gameLost && gx * gy - areOpen - areMarked == 0;
  drawStatus();
}

function drawStatus() {
  push();

  fill("orange");
  let msg = "";
  // print(gameLost, gx * gy, areOpen, areMarked, gx * gy - areOpen - areMarked);
  const gameFinished = gx * gy - areOpen - areMarked == 0;
  const time = floor((currTime - startTime) / 1000) + "s";

	noStroke();
	textAlign(CENTER, CENTER);
	textSize(gs * 0.6 + abs(sin(frameCount * 0.04)) * gs * 0.2);
  if (gameLost) {
    fill("red");
    msg = "Don't disturb the unicorn\nor they loose their magic...";
		text(msg, width / 2, height / 2);
    msg = "Don't disturb the unicorn or they loose their magic...";
  } else if (!gameFinished) {
    msg = "Time lapsed: " + time;
    currTime = millis();
  } else {
    // finished
    fill("green");
    msg = "No unicorn hit!\nYou won in: " + time;
		text(msg, width / 2, height / 2);
    msg = "No unicorn hit! You won in: " + time;
  }

  textSize(gs * 0.48);
  text(msg, width / 2, gy * gs + gs / 2);

  pop();
}

function mousePressed() {
  if (gameLost || gameWon) {
    setup();
    return;
  }

  var xx = floor((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / gs);
  var yy = floor((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / gs);
  // check range
  if (xx < 0 || yy < 0 || xx >= gx || yy >= gy) return;

  if (mouseButton === LEFT) {
    grid[yy][xx].open();
  } else if (mouseButton === RIGHT) {
    grid[yy][xx].toggleMark();
  }
}
